parameters.jsonBody:
={
  "embeds": [{
    "title": "🚨 {{ $json.labels.alertname }}",
    "description": "{{ $json.annotations.description || $json.annotations.summary }}",
    "fields": [
      { "name": "Namespace", "value": "{{ $json.labels.namespace }}", "inline": true },
      { "name": "Severity", "value": "{{ $json.labels.severity }}", "inline": true },
      { "name": "Instance", "value": "{{ $json.labels.instance || 'N/A' }}", "inline": true }
    ],
    "color": {{ $json.labels.severity === 'critical' ? 16711680 : ($json.labels.severity === 'warning' ? 16776960 : 65280) }},
    "timestamp": "{{ new Date().toISOString() }}",
    "footer": { "text": "Home Lab Monitoring • Admin Alert" }
  }]
}
